  <main v-else class="not-found"><h1>赛事未找到</h1><router-link to="/contests">返回赛事页</router-link></main>
</template>

<script setup>
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { findContest } from '@/data/contestCatalog'
import { getContestArt } from '@/data/contestArt'
const route = useRoute()
const openFaq = ref(0)
const contest = computed(() => findContest(route.params.id))
const artFor = id => getContestArt(id)
const cover = computed(() => artFor(contest.value?.id))
const related = computed(() => contest.value?.similar.map(findContest).filter(Boolean) || [])
const audience = computed(() => contest.value?.format.includes('团队') ? '适合希望通过协作完成算法、软件或创新项目的同学；建议尽早寻找互补队友，并在正式比赛前建立清晰分工。' : '适合希望系统提升相关技术能力、积累高质量竞赛经历的同学；可从历年题目、规则解读和校内训练开始。')
const faq = computed(() => contest.value ? [{ q: '什么时候开始报名？', a: `通常在${contest.value.month}进入报名或准备期，最终日期以学校与官方当届公告为准。` }, { q: '需要先经过校赛、省赛吗？', a: `常见路径为：${contest.value.progression}。校内阶段：${contest.value.school}；山东阶段：${contest.value.shandong}。` }, { q: '个人可以参赛吗？', a: `本赛事为${contest.value.format}，请按当届赛道规则确认人数、指导教师和作品要求。` }] : [])
</script>

